-- 008: стартовый гайд «Права в Испании» для раздела «Полезно».
-- Идемпотентно: если страница с таким адресом уже есть, она не трогается (правки из админки не затираются).
-- Картинки лежат в public/useful/ и подключаются по адресу /useful/<имя>.png.

insert into public.useful_sections (title, sort)
select $j${"ru":"Права в Испании","hy":""}$j$::jsonb, coalesce((select max(sort) from public.useful_sections), 0) + 10
where not exists (select 1 from public.useful_sections where title->>'ru' = 'Права в Испании');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-prava-start', '🧭', 'published', 10,
       $j${"ru":"Права в Испании: с чего начать","hy":""}$j$::jsonb, $j${"ru":"Свои права, обмен или экзамены с нуля. Выберите свой сценарий и перейдите к нужной инструкции.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"image","url":"/useful/choose-path.png","caption":"От страны выдачи ваших прав зависит, нужны ли экзамены"},{"type":"text","text":"# Выберите свой сценарий\nВсё начинается с вопроса, где и когда выданы ваши действующие права. Есть три варианта.\n\n**Права из страны ЕС или ЕЭП** (плюс Исландия, Лихтенштейн, Норвегия) действуют в Испании до конца своего срока. Менять их на испанские не обязательно, но у резидента Испании появляются обязанности. Подробности: [Свои права: можно ли ездить и как обменять](/useful/gid-obmen-prav).\n\n**Права из страны, с которой у Испании есть соглашение об обмене.** Экзамены для легковых и мотоциклетных категорий не нужны, платится пошлина 28,87 €. Подробности там же.\n\n**Страна без соглашения или прав нет вообще.** Придётся пройти путь целиком: медсправка, теория, практика. Начните с инструкции [Права с нуля: документы и запись на экзамен](/useful/gid-prava-s-nulya)."},{"type":"table","headers":["Ваша ситуация","Что делать","Где читать"],"rows":[["Права ЕС / ЕЭП","Ездить до конца срока; при бессрочных или долгих правах — продлить по испанским правилам","Свои права"],["Страна с соглашением (например, Украина, Грузия, Молдова)","Обмен без экзаменов для категорий A1, A, B, B+E","Свои права"],["Страна без соглашения (например, Россия, Беларусь, Казахстан, Армения)","Сдавать заново: медсправка, теория, практика","Права с нуля"],["Прав нет","Тот же путь, что и без соглашения","Права с нуля"]]},{"type":"callout","tone":"warn","text":"Главное ограничение обмена: права должны быть получены **до** того, как вы стали легальным резидентом Испании. Исключение DGT делает только для Южной Кореи. Цепочка «российские права → права третьей страны → испанские» тоже не работает: права, которые сами получены обменом, к обмену не принимают."},{"type":"text","text":"# Все материалы раздела\n1. [Права в Испании: с чего начать](/useful/gid-prava-start) (вы здесь)\n2. [Свои права: можно ли ездить и как обменять](/useful/gid-obmen-prav)\n3. [Права с нуля: документы и запись на экзамен](/useful/gid-prava-s-nulya)\n4. [Теория: как проходит экзамен и как готовиться](/useful/gid-teoriya)\n5. [Автошкола и практический экзамен](/useful/gid-praktika)\n6. [После экзамена: временные права, пластик, баллы](/useful/gid-posle-ekzamena)\n7. [Деньги и сроки](/useful/gid-dengi-i-sroki)\n8. [Испанский для практики: команды и слова](/useful/gid-ispanskiy-dlya-praktiki)"},{"type":"text","text":"# Что даёт категория B\nПраво водить легковые автомобили с разрешённой максимальной массой до 3500 кг и не более чем с восемью пассажирскими местами, не считая водительского. Минимальный возраст — 18 лет. Через три года стажа по категории B на территории Испании можно ездить и на мотоцикле до 125 см³ (класс A1 с ограничениями)."},{"type":"text","text":"# Слова, которые встретятся дальше"},{"type":"table","headers":["Слово","Что это"],"rows":[["DGT","Dirección General de Tráfico: ведомство, которое выдаёт права и проводит экзамены"],["Jefatura","Провинциальное управление DGT: сюда идут с документами лично"],["Sede electrónica","Электронная канцелярия DGT (sede.dgt.gob.es): заявления, оплата пошлин, статус документов"],["NIE / TIE","Идентификационный номер иностранца и пластиковая карточка резидента с этим номером"],["Padrón","Регистрация по месту жительства в мэрии; справка называется certificado de empadronamiento"],["Cita previa","Запись на приём. Без неё в большинство управлений не пускают"],["Cl@ve","Государственная система входа на сайты ведомств; заменяет логин и электронную подпись"],["Tasa","Государственная пошлина. У каждой в каталоге DGT свой номер: 2.1, 2.3, 4.5 и так далее"],["CRC","Centro de Reconocimiento de Conductores: медцентр, аккредитованный DGT для справок водителям"],["Canje","Обмен иностранных прав на испанские"],["Expediente","Экзаменационное дело: в нём хранятся заявка, оплата, медсправка и результаты"],["Apto / No apto","«Сдал» и «не сдал» в результатах экзамена"],["miDGT","Официальное мобильное приложение DGT: документы, баллы, результаты"]]}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-prava-start');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-obmen-prav', '🌍', 'published', 20,
       $j${"ru":"Свои права: можно ли ездить и как обменять","hy":""}$j$::jsonb, $j${"ru":"Шесть месяцев на своих правах, права ЕС, страны с соглашением и пошаговая процедура обмена.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"text","text":"# Сколько можно ездить на иностранных правах\nДо шести месяцев с того момента, как Испания стала вашим обычным местом жительства (*residencia normal*). Для иностранца этот статус считается только при легальном пребывании, подтверждённом документом. На практике многие отсчитывают срок от даты выдачи карточки TIE. Если у вас сложная миграционная история, лучше заранее получить письменный ответ в управлении DGT.\n\nМеждународное водительское удостоверение шесть месяцев не продлевает: оно работает только вместе с действующими национальными правами."},{"type":"callout","tone":"warn","text":"Ездить по иностранным правам, которые в Испании уже не действуют, — это вождение без прав: штраф и риск того, что машину задержат. Прокатные компании тоже смотрят на сроки и после полугода обычно отказывают."},{"type":"text","text":"# Права ЕС и ЕЭП\nУдостоверение из страны ЕС или ЕЭП действует в Испании до конца своего срока. Но когда вы живёте в Испании, к нему применяются испанские правила.\n\n- Если срока нет или он длиннее испанского (категория B здесь действует 10 лет, после 65 лет — 5), права нужно продлить по испанским правилам: с медсправкой из аккредитованного центра и пошлиной 4.3 — 24,58 €.\n- Если срок истёк, права утеряны или испорчены, продлить их или получить дубликат в стране выдачи нельзя. Это делает DGT, а документ меняют на испанский.\n- Если вы получили нарушение со списанием баллов, DGT заводит испанское дело, и права тоже придётся обменять.\n\nПошлина за обмен прав ЕС — 28,87 €, экзамены не нужны. Порядок и запись смотрите на странице DGT «Trasladarte a España desde un país de la Unión Europea»."},{"type":"text","text":"# Страны с соглашением об обмене\nОбмен без экзаменов возможен для категорий A1, A, B и B+E. В списке DGT 34 страны. Из постсоветского пространства в нём есть **Украина** (с 31.10.2010), **Грузия** и **Молдова** (обе с 29.09.2024). **Россия, Беларусь, Казахстан, Армения, Узбекистан и Азербайджан в списке не значатся.** Список пополняется, поэтому смотрите актуальную версию на странице DGT «Países con convenio de canjes»."},{"type":"link","label":"Список стран с соглашением","url":"https://www.dgt.es/nuestros-servicios/permisos-de-conducir/permisos-extranjeros-y-de-fuerzas-y-cuerpos-de-seguridad/canjes-de-permisos/paises-con-convenio-de-canjes/","description":"Официальная страница DGT"},{"type":"checklist","title":"Условия обмена","items":["Вы резидент Испании","Иностранные права действующие: оригинал у вас заберут","Права получены до того, как вы стали резидентом Испании","Сами права получены по экзамену, а не обменом удостоверения третьей страны"]},{"type":"image","url":"/useful/exchange-process.png","caption":"Обмен идёт в два этапа: проверка прав, затем заявление и визит"},{"type":"steps","title":"Как проходит обмен","items":[{"title":"Медицинская справка","text":"Из аккредитованного центра (CRC). Для категорий A и B нужно заключение группы I. Справку получают до подачи заявления."},{"title":"Запрос на проверку прав","text":"Откройте страницу «Canje de permisos de países extracomunitarios» на sede.dgt.gob.es и выберите свою страну. DGT направит запрос в страну выдачи. Ответ приходит от нескольких дней до нескольких недель."},{"title":"Письмо с кодом","text":"После положительного ответа на почту придёт письмо с кодом заявки (*localizador*). Сохраните его: он понадобится дальше."},{"title":"Заявление на обмен","text":"Вернитесь в сервис, выберите управление DGT, где закончите процедуру, заполните данные прав, приложите сканы и оплатите пошлину 2.3 (28,87 €) или укажите номер уже оплаченной."},{"title":"Визит в управление","text":"Обмен завершается только лично: оригинал иностранных прав сдаётся в управлении DGT. Нужна предварительная запись онлайн или по телефону 060. Там же выдают временное разрешение."},{"title":"Пластиковая карта","text":"Придёт по почте. Ориентир DGT — около полутора месяцев."}]},{"type":"table","headers":["Что понадобится","Комментарий"],"rows":[["Медицинская справка","Действительна 90 дней"],["Паспорт или разрешение на проживание","Документ, удостоверяющий личность"],["Подтверждение резиденции","TIE или сертификат о регистрации гражданина ЕС"],["Подтверждение, что вы не были резидентом, когда получали права","Например, карточка резидента или студента, справка о регистрации иностранца, консульская справка"],["Оригинал иностранных прав","Заберут при обмене"],["Оплаченная пошлина","2.3 — 28,87 €"]]},{"type":"callout","tone":"success","text":"Итого по деньгам: пошлина 28,87 € и медосмотр, в разных центрах обычно 25–60 €. Для грузовых и автобусных категорий (C, D) нужны дополнительные испытания и пошлина 2.1 — 94,05 €."},{"type":"faq","items":[{"q":"У меня права из Армении. Их можно обменять?","a":"Армении нет в списке стран с соглашением, поэтому обмен без экзаменов недоступен. Нужно получать права заново: [Права с нуля](/useful/gid-prava-s-nulya)."},{"q":"Права выданы, когда я уже жил в Испании. Что делать?","a":"Такие права не обмениваются (исключение — Южная Корея). Путь только через экзамены."},{"q":"Можно ли сначала поменять российские права на грузинские, а потом на испанские?","a":"Нет. Соглашения исключают права, полученные обменом удостоверения третьей страны. Кроме того, DGT требует доказать, что права получены до того, как вы стали резидентом Испании."},{"q":"Нужен ли Cl@ve, чтобы подать заявку?","a":"Для онлайн-подачи нужна электронная идентификация: Cl@ve или электронный сертификат. Без неё можно оплатить пошлину в банке и подать документы лично в управлении, но каждый шаг тогда занимает больше времени."}]}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-obmen-prav');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-prava-s-nulya', '🚗', 'published', 30,
       $j${"ru":"Права с нуля: документы и запись на экзамен","hy":""}$j$::jsonb, $j${"ru":"Требования DGT, медсправка, пошлина 2.1, Cl@ve и подача заявки на теоретический экзамен.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"image","url":"/useful/roadmap-from-scratch.png","caption":"Семь шагов от подготовки до экзамена по практике"},{"type":"text","text":"# Кто может подать\nПо требованиям DGT нужно, чтобы вы:\n\n- легально жили в Испании и могли это подтвердить документом: для граждан не из ЕС это карточка TIE, для граждан ЕС — сертификат о регистрации;\n- достигли 18 лет (для категории B);\n- имели психофизические способности, достаточные для вождения: это подтверждает медцентр;\n- не были лишены права управления по решению суда;\n- не имели действующих прав того же класса, выданных в другой стране ЕС или ЕЭП."},{"type":"callout","tone":"warn","text":"Теорию учите с первого дня, а с бумагами не торопитесь. Медсправка годна для подачи заявления 90 дней. Если пройти медкомиссию заранее и затянуть подготовку, справка успеет закончиться, а новую придётся делать и оплачивать заново. Идите за справкой, когда до готовности остаётся месяц-полтора."},{"type":"steps","title":"Путь в семь шагов","items":[{"title":"Подготовка к теории","text":"Учите вопросы DGT. Сдаётся тест на компьютере."},{"title":"Медицинская справка","text":"В аккредитованном центре (CRC)."},{"title":"Пошлина 2.1","text":"94,05 €. Даёт право на две попытки экзаменов."},{"title":"Заявление на экзамен","text":"Через автошколу или самостоятельно."},{"title":"Теоретический экзамен","text":"30 вопросов, не более трёх ошибок."},{"title":"Автошкола","text":"Уроки вождения и ведение дела."},{"title":"Практический экзамен","text":"Езда не менее 25 минут."}]},{"type":"text","text":"# Шаг 2. Медицинская справка\nСправку (*informe de aptitud psicofísica*) выдают только в аккредитованных DGT центрах CRC. Они часто стоят рядом с управлениями DGT и крупными автошколами. Ближайший центр находится в официальном реестре на сайте DGT: выберите провинцию и населённый пункт.\n\nНа ресепшене скажите:\n\n*Necesito el informe de aptitud psicofísica para obtener el permiso B, grupo uno.*\n(нэсэси́то эль информэ дэ аптиту́д сикофи́сика пара обтэнэ́р эль пэрми́со бэ, гру́по у́но)\n\nЧто вас ждёт: анкета о болезнях, операциях, давлении, лекарствах и алкоголе; проверка зрения по буквам и цветам; тест на оценку скорости и тест на координацию. Обычно всё занимает 20–30 минут. Цена зависит от города и центра: ориентируйтесь на 25–60 €, оплату уточняйте заранее, некоторые центры берут только наличные."},{"type":"callout","tone":"info","text":"Фотография на права часто делается прямо в медцентре и передаётся в DGT электронно. Если фото и подпись у DGT уже есть, повторно приносить их не нужно. Перед уходом спросите: *¿La foto y la firma se envían electrónicamente a la DGT?*  Именно этот снимок попадёт на пластиковую карточку, так что на осмотр лучше прийти выспавшимся."},{"type":"text","text":"# Шаг 3. Государственная пошлина\nЭкзамены оплачиваются пошлиной **2.1 — 94,05 €**. Платят на сайте DGT в разделе пошлин (*Tasas*). Есть два способа:\n\n- *Pagar tasas* — оплата картой онлайн, нужен вход через Cl@ve или сертификат;\n- *Generar modelo 791* — сформировать квитанцию и оплатить в банке. Вход не нужен.\n\nВ каталоге выберите группу 2, «Permisos para conducción», строку 2.1, «Obtención del permiso de conducción».\n\nОдна оплата даёт право на две *convocatorias*, то есть на два вызова на экзамен. Если вы получили два результата «No apto» (неважно, дважды на одной части или по разу на разных), нужны новая заявка и новая пошлина. Сданный теоретический экзамен действует два года: если за это время права не получены, всё придётся сдавать заново."},{"type":"callout","tone":"warn","text":"Пошлина 2.3 в интерфейсе подписана «por pérdida de puntos» (за потерю баллов). Не выбирайте её для получения прав: она нужна для обмена иностранных прав без практики и для восстановления после потери баллов. Для экзаменов нужна именно 2.1."},{"type":"text","text":"# Cl@ve или сертификат\nВсё, что делается из дома (оплата картой, подача заявления, приложение miDGT), требует электронной идентификации. DGT принимает три способа:\n\n- **Cl@ve Móvil** — приложение (включает Cl@ve PIN), нужна предварительная регистрация;\n- **электронный сертификат** — любой квалифицированный; самый распространённый выдаёт FNMT, в Валенсии есть собственный ACCV, который оформляют полностью онлайн;\n- **Cl@ve Permanente** — логин, пароль и код из SMS.\n\nБез этого тоже можно: оплатить квитанцией в банке и отнести документы в управление DGT лично."},{"type":"text","text":"# Шаг 4. Заявка на теоретический экзамен\nЕсть два пути.\n\n## Через автошколу\nПриносите медсправку и квитанцию, дальше школа подаёт документы и записывает вас сама. Плюсы: не нужны ни Cl@ve, ни испанский. Минусы: школа записывает в своём темпе, дата может оказаться на несколько месяцев вперёд, иногда просят оплатить свой курс по теории.\n\n## Самостоятельно (por libre)\nПроцедура называется *Solicitud de examen teórico por libre*. Подать можно онлайн через электронный реестр (по Cl@ve, сертификату или DNIe) либо лично в любом управлении DGT. Что приложить:\n\n- официальное заявление **Mod.04**. Подписывая, вы подтверждаете, что не лишены права управления и что у вас нет прав того же класса в другой стране ЕС;\n- медсправку (действует 90 дней);\n- подтверждение оплаты пошлины или карту, если платите в офисе;\n- при личной подаче — оригиналы документов."},{"type":"table","headers":["Поле в Mod.04","Что вписать"],"rows":[["Datos del solicitante","ФИО, номер NIE, дата рождения, адрес. Если у вас одна фамилия, второе поле (*segundo apellido*) остаётся пустым"],["Domicilio a efecto de notificaciones","Адрес, по которому DGT будет писать и куда придёт пластик. Тип улицы (Calle, Avenida, Plaza), название, номер дома, затем при необходимости корпус, подъезд, этаж и дверь"],["Centro de reconocimiento","Название медцентра, где получено заключение"],["Clase de permiso","B (или другая нужная категория)"],["Transmisión","Механика или автомат"],["Idioma de la prueba teórica","Язык, на котором будете сдавать"],["Centro de examen","Экзаменационный центр, где хотите сдавать"],["Autoescuela","Реквизиты школы заполняет школа. Подаёте самостоятельно — поля остаются пустыми"],["Auriculares / ampliación de tiempo","Наушники с озвучкой вопросов и дополнительное время: просят заранее отметкой в бланке, решение принимает провинциальное управление DGT"]]},{"type":"callout","tone":"info","text":"Данные из примера в бланке Mod.04 всегда заполняйте своими. Код DIR3 в углу бланка заполнять не нужно."},{"type":"faq","items":[{"q":"Что лучше: автошкола или por libre?","a":"Самостоятельно быстрее и дешевле, если вы уверенно пользуетесь Cl@ve. Через автошколу проще, особенно без испанского, но школа может записать на более позднюю дату и взять доплату."},{"q":"Нужен ли TIE старше шести месяцев?","a":"В официальных требованиях DGT для обычного резидента такого срока не указано, требуется легальный статус, подтверждённый документом. Если конкретное управление просит больше, попросите назвать норму."},{"q":"Что делать, если справка закончилась до подачи?","a":"Придётся пройти медкомиссию заново. Если же вы успели подать заявление и открыть экзаменационное дело, справка остаётся в нём, а экзамен может состояться позже."}]}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-prava-s-nulya');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-teoriya', '📝', 'published', 40,
       $j${"ru":"Теория: как проходит экзамен и как готовиться","hy":""}$j$::jsonb, $j${"ru":"Формат теста, языки, что взять с собой, где смотреть результат и чем готовиться.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"image","url":"/useful/theory-exam.png","caption":"Теория для категории B: 30 вопросов, 30 минут, не больше трёх ошибок"},{"type":"text","text":"# Формат\nЭкзамен проходит на компьютере с сенсорным экраном. В тесте для категории B **30 вопросов**, на них даётся **30 минут**, допускается **не больше 3 ошибок**.\n\nЯзык можно выбрать при подаче заявки. Для категорий B, A1 и A2 это испанский, региональные языки (в своём регионе: каталанский в Каталонии и на Балеарах, валенсийский в Валенсии, эускера в Стране Басков и Наварре, галисийский в Галисии), английский, французский и немецкий. Для категорий C и D перечень короче, для AM, BE и некоторых других доступен только испанский и региональные языки. Для B есть версия «lectura fácil» на упрощённом испанском. Наушники с озвучкой вопросов и дополнительное время можно запросить заранее."},{"type":"text","text":"# Как проходит день экзамена\n1. Возьмите TIE или документ, указанный в вашем деле, и ручку.\n2. Телефон выключите полностью. За писк или вибрацию могут удалить с экзамена, режима «без звука» недостаточно.\n3. Ждите на улице. В зал заходят группами, по фамилиям.\n4. На первом экране вводите номер документа и выбираете язык. Дальше идёт по одному вопросу на экран, кнопки «Anterior» и «Siguiente» переключают вопросы.\n5. В конце нажмите «Finalizar test». Пока вы его не нажали, тест не завершён."},{"type":"text","text":"# Где смотреть результат\nВ приложении miDGT, по официальному сроку, примерно через час после экзамена. На сайте DGT в разделе *Consulta de notas de examen* оценка появляется в тот же день после 17:00. Нужны номер NIE, дата экзамена, класс permiso и дата рождения. Иногда результат появляется позже. **Apto** — сдали, **No apto** — не сдали."},{"type":"callout","tone":"success","text":"Если результат «No apto», это не конец: одна пошлина 2.1 даёт две попытки."},{"type":"text","text":"# Как готовиться\n**В этом приложении.** Тесты идут по порядку, после каждого есть разбор. Каждые 10 тестов вас ждёт проверка на закрепление, а ошибки возвращаются в раздел «Ошибки» на повторение, пока вы не исправите их.\n\n**Официальный тренажёр DGT.** Бесплатный, без регистрации. Открывается со страницы «Requisitos, preparación y presentación a examen» кнопкой «Test de Examen». Вопросов в нём немного, он нужен, чтобы увидеть интерфейс и порядок работы: язык выбирается на первом экране, документ на репетиции можно не вводить.\n\n**Другие сервисы.** Для ПДД Испании есть и испаноязычные тренажёры, например Practicatest, Todotest и AEOL."},{"type":"callout","tone":"info","text":"Совет: учите вопросы на испанском и подключайте перевод на русский или армянский как подсказку. Так вы начнёте понимать инструктора, экзаменатора и дорожные знаки, а сдавать можно на любом языке из списка."},{"type":"link","label":"Официальный тренажёр DGT","url":"https://www.dgt.es/nuestros-servicios/permisos-de-conducir/obtener-un-nuevo-permiso-de-conducir/requisitos-preparacion-y-presentacion-a-examen/","description":"Страница с кнопкой «Test de Examen»"}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-teoriya');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-praktika', '🛣️', 'published', 50,
       $j${"ru":"Автошкола и практический экзамен","hy":""}$j$::jsonb, $j${"ru":"Как выбрать школу, что спросить до оплаты, как проходит практика и на что смотрит экзаменатор.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"text","text":"# Передача дела в автошколу\nЕсли теорию вы сдавали самостоятельно, дальше нужно передать своё дело в школу: сама она его не видит. Принесите:\n\n- документ о сданной теории или данные экзаменационного дела;\n- подтверждение оплаченной пошлины с номером;\n- данные медицинского заключения;\n- документы личности и резиденции.\n\nШкола проверит, сколько попыток осталось по вашей пошлине, и поставит вас в очередь к инструктору. Платить пошлину повторно, пока попытки не исчерпаны, не нужно.\n\nПрактику почти все сдают через автошколу: экзаменационная машина должна быть с дублирующими педалями, а школа заодно ведёт дело в DGT. Формально можно и самостоятельно, но для этого нужна учебная лицензия, назначенный сопровождающий и машина с дублирующим управлением, поэтому на практике так почти никто не делает."},{"type":"text","text":"# Что нужно знать про школы\n- Обязательного теоретического курса нет. Школа может дать доступ к тестам и провести занятия по теории, но закон этого не требует.\n- Обязательного минимума уроков вождения в требованиях DGT нет. Минимумы устанавливает сама школа. Обычно продают пакеты занятий, урок идёт 45 минут.\n- К практике допускают после сданной теории.\n- **Механика или автомат.** Сдавшему на автомате ставят код 78: ездить можно только на автомобилях с автоматической коробкой. Если планируете ездить на механике, сдавайте на механике.\n- Очередь на практику зависит от провинции, и в соседней она может быть короче. Сдавать можно в другой провинции: для этого дело переносят (*traslado de expediente*), обычно за небольшую пошлину; назначенного экзамена на этот момент быть не должно, оставшиеся попытки сохраняются."},{"type":"checklist","title":"Что спросить у школы до оплаты (лучше письменно)","items":["Сколько стоит matrícula (вступительный взнос) и входит ли в неё ведение дела","Сколько длится одно занятие: 45, 50 или 60 минут","Цена одного занятия и пакета","Сколько стоит подача машины и преподавателя на экзамен","Сколько стоит повторная подача после неудачи","Какая реальная очередь к инструктору и на экзамен","Есть ли инструктор, который говорит по-английски или по-русски","Можно ли перенести дело в другую школу или провинцию"]},{"type":"callout","tone":"warn","text":"Дополнительные занятия, подача машины на каждый экзамен и повторная подача после неудачи оплачиваются отдельно от пакета. Узнайте цены заранее."},{"type":"text","text":"# Практический экзамен\nМинимальная продолжительность езды для категорий A1, A2, B и B+E — **25 минут**. Приём кандидата, подготовка и проверка машины, специальные манёвры и объявление результата в это время не входят. Место и время старта обычно известны за пару дней, поэтому последнее занятие хорошо взять накануне, прямо в экзаменационной зоне."},{"type":"image","url":"/useful/practical-start.png","caption":"Типичный порядок перед стартом: инструктор покажет детали вашей зоны"},{"type":"text","text":"# На что смотрит экзаменатор\nОценка идёт по официальным критериям DGT. Чаще всего теряют баллы на этом:\n\n- **Наблюдение.** Оценивается отдельно при начале движения, в обычном движении, при перестроении, на перекрёстках и при остановке. Экзаменатор видит только то, что видно со стороны, поэтому голову поворачивайте заметно: сначала зеркало, затем взгляд через плечо.\n- **Пешеходы.** Перед каждым переходом сбавляйте скорость и смотрите в обе стороны.\n- **Знак STOP.** Закон требует полной остановки в нужном месте. Если оттуда не видно дорогу, аккуратно продвиньтесь вперёд и остановитесь снова. Сколько секунд стоять — норма не определяет, важна реальная остановка и реальный обзор.\n- **Скорость.** Превышать нельзя, но и ехать неоправданно медленно тоже: для этого есть отдельный пункт.\n- **Дистанция** до впереди идущего и боковая при объезде, особенно рядом с велосипедистами.\n- **Управление машиной:** руль, сцепление, коробка, их согласованность.\n- **Круговое движение.** Перед выездом посмотрите на тех, кто перестраивается. «Всегда держитесь правой полосы» — не универсальное правило: на круговых перекрёстках с разметкой по полосам нужная полоса может быть другой, смотрите на разметку и стрелки.\n- **Ориентирование.** Не поняли, куда ехать, — спросите: *¿Puede guiarme?* Указание экзаменатора не отменяет знаков и разметки: «поверните налево» значит «сделайте это там, где это разрешено и безопасно»."},{"type":"callout","tone":"info","text":"Больше всего даёт подготовка именно к вашей экзаменационной зоне. Заранее покатайтесь по её маршрутам, запомните сложные места: знаки за деревьями, короткие разрывы в разметке для левого поворота, круговые перекрёстки с разметкой по полосам. Узнайте у инструктора, какие привычки приняты у вас: свет под мостом, передача на круге, парковка."},{"type":"text","text":"# Как читать отчёт об ошибках\nЭкзаменатор отмечает ошибки кодами. Полная таблица есть на странице «Examen práctico en vías abiertas» вместе с PDF «Criterios de calificación». Верхний уровень выглядит так:"},{"type":"table","headers":["Код","Что оценивается"],"rows":[["1","Предварительные проверки"],["2","Посадка: сиденье, зеркала, ремень"],["3","Начало движения"],["4","Обычное движение: полоса, дистанция, скорость, наблюдение"],["5","Перестроение"],["6","Обгон"],["7","Перекрёстки"],["8","Разворот"],["9","Остановка и стоянка"],["11","Соблюдение сигналов и знаков: регулировщик, светофоры, разметка"],["12","Свет"],["13","Органы управления: сцепление, тормоз, газ, коробка, руль"],["14","Прочие органы: дворники, звуковой сигнал, видимость"],["15","Во время экзамена: создание опасности, наезд на бордюр, невыполнение указаний"]]},{"type":"callout","tone":"info","text":"Если вы не согласны с отчётом, жалобу руководителю провинциального управления DGT можно подать в течение 15 рабочих дней после уведомления. Затем возможна апелляция директору DGT в течение месяца."},{"type":"callout","tone":"success","text":"Не сдать практику с первого раза — обычное дело. Разберите отчёт с инструктором и пересдайте."}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-praktika');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-posle-ekzamena', '🪪', 'published', 60,
       $j${"ru":"После экзамена: временные права, пластик, баллы","hy":""}$j$::jsonb, $j${"ru":"Временное разрешение, статус пластиковой карты, международные права и система баллов.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"text","text":"# Временное разрешение\nКак только в результатах появился «Apto», на сайте DGT в разделе *Consulta de notas de examen* можно получить временное разрешение. Введите те же данные, что для теории, нажмите *Obtener autorización* и сохраните PDF. Оно действует **не более трёх месяцев** и предъявляется вместе с документом, удостоверяющим личность. Ссылка со временем пропадает, поэтому сразу сохраните и распечатайте файл. В приложении miDGT документ появляется позже."},{"type":"text","text":"# Пластиковая карта\nСтатус проверяется бесплатно по NIE и дате рождения на странице *Consulta del estado del permiso de conducir*. Этапы идут по цепочке: дело в работе, карточку печатают, передана на почту. Номера для отслеживания на почте нет, видна только дата отправки.\n\nDGT ориентирует на полтора месяца. По отзывам в чатах бывает и дольше. До подачи проверьте, что адрес указан полностью и что на почтовом ящике есть ваша фамилия."},{"type":"text","text":"# Международные права\nПосле получения испанских прав можно оформить международное водительское удостоверение. Пошлина 4.5 — 10,51 €. Нужны документ, удостоверяющий личность, цветная фотография 32 × 26 мм на светлом фоне и заполненная форма (Model 3). Подать можно онлайн (по Cl@ve или сертификату): тогда документ готов через два дня. Или лично в управлении DGT по записи (онлайн или по телефону 060). Срок действия — один год, продлить нельзя, потом оформляют новое."},{"type":"image","url":"/useful/points.png","caption":"Начинающий водитель стартует с 8 баллами"},{"type":"text","text":"# Что меняется после получения прав\nПервые права выдают с **8 баллами**. Через два года без списаний их становится 12, затем ещё через три года без нарушений — 14, а ещё через три — максимум, 15. Баллы списываются за нарушения.\n\nПервый год на заднем стекле нужна наклейка **L**, которая показывает, что водитель начинающий. Первые два года действует пониженный предел алкоголя: 0,15 мг/л в выдыхаемом воздухе вместо общих 0,25."},{"type":"faq","items":[{"q":"Можно ли учесть мой водительский стаж из другой страны?","a":"Иногда да. DGT может внести в права отметку о том, что вы владеете иностранными правами, которые нельзя обменять, и тогда вы не считаетесь начинающим водителем (больше баллов, без наклейки L). Для этого обычно нужна справка о стаже от органа, выдавшего права. Практика отличается по управлениям: сначала спросите автошколу, приложит ли она справку к делу, и уточните решение в своей Jefatura."},{"q":"Где смотреть баллы?","a":"В приложении miDGT или на сайте DGT в разделе «Consulta y justificante de puntos»."},{"q":"Временное разрешение действует за границей?","a":"На странице DGT оно описано как документ для вождения в Испании. Для поездок за границу лучше дождаться пластика и оформить международные права."}]}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-posle-ekzamena');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-dengi-i-sroki', '💶', 'published', 70,
       $j${"ru":"Деньги и сроки: сколько это стоит и как долго ждать","hy":""}$j$::jsonb, $j${"ru":"Государственные пошлины DGT, рыночные цены и официальные сроки в одном месте.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Сверено с официальными страницами DGT в октябре 2026. Правила и размеры пошлин меняются, поэтому перед оплатой и подачей документов откройте актуальную страницу на sede.dgt.gob.es."},{"type":"text","text":"# Государственные пошлины DGT\nСуммы по каталогу пошлин в 2026 году:"},{"type":"table","headers":["Пошлина","Сумма","За что"],"rows":[["2.1","94,05 €","Получение прав через экзамены, две попытки"],["2.2","44,58 €","Получение лицензий (например, LCM, LVA)"],["2.3","28,87 €","Обмен иностранных прав без практики; восстановление после потери баллов"],["4.1","8,67 €","Отметки в деле, справки, перенос дела"],["4.3","24,58 €","Продление срока действия прав"],["4.4","20,81 €","Дубликат прав"],["4.5","10,51 €","Международные права и подобные разрешения"]]},{"type":"text","text":"# За что ещё платят\nЭто рыночные цены, они зависят от города и школы. Ориентиры по обзорам цен 2026 года:"},{"type":"table","headers":["Статья","Ориентир"],"rows":[["Медсправка в CRC","35–50 €, в разных центрах встречается от 25 до 60 €"],["Matrícula и ведение дела в автошколе","в среднем около 200 €, в разных городах от 45 до 400 €"],["Занятие вождением (45 минут)","в среднем около 27 €"],["Подача машины и преподавателя на экзамен","платится за каждую попытку отдельно"],["Обмен прав","28,87 € и медосмотр, итого около 55–90 €"],["Права с нуля через автошколу","в среднем порядка 1300–1400 €; без школьной теории дешевле"]]},{"type":"callout","tone":"warn","text":"Это средние значения из публичных обзоров, а не гарантия. Считайте по прайсу своей школы. Основная часть расходов — занятия с инструктором и подача машины на экзамен, и каждая пересдача добавляет и то и другое."},{"type":"image","url":"/useful/deadlines.png","caption":"Официальные сроки, на которые можно опираться"},{"type":"table","headers":["Что","Срок","Откуда"],"rows":[["Медсправка для подачи заявления","90 дней","Требования DGT"],["Сданная теория хранится в деле","2 года","Требования DGT"],["Временное разрешение после экзамена","до 3 месяцев","Autorización provisional"],["Изготовление пластика","около 1,5 месяца","Ориентир DGT"],["Международные права","год","Страница DGT"]]},{"type":"text","text":"Общей длительности процедуры нет: она складывается из очередей в вашей провинции и в вашей школе. Официальных сроков всего несколько, они в таблице выше."},{"type":"link","label":"Каталог пошлин DGT","url":"https://www.interior.gob.es/opencms/es/servicios-al-ciudadano/tramites-y-gestiones/tasas/trafico/","description":"Официальная страница Министерства внутренних дел"}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-dengi-i-sroki');

insert into public.useful_pages (section_id, slug, icon, status, sort, title, summary, blocks, published_at)
select (select id from public.useful_sections where title->>'ru' = 'Права в Испании' limit 1), 'gid-ispanskiy-dlya-praktiki', '🗣️', 'published', 80,
       $j${"ru":"Испанский для практики: команды и слова","hy":""}$j$::jsonb, $j${"ru":"Что говорит инструктор и экзаменатор и как называются части машины.","hy":""}$j$::jsonb, $j${"ru":[{"type":"callout","tone":"info","text":"Читается как написано. Ударные слоги отмечены, звук «ll» и «y» передан как «й»."},{"type":"text","text":"# Команды на дороге"},{"type":"table","headers":["Испанский","Что значит","Как читается"],"rows":[["Gire a la derecha / a la izquierda","Поверните направо / налево","хи́рэ а ла дэрэ́ча / а ла искье́рда"],["Siga recto","Езжайте прямо","си́га рэ́кто"],["Tome la primera / segunda salida","Выезжайте по первому / второму съезду (на круге)","то́мэ ла примэ́ра / сэгу́нда сали́да"],["En la próxima, a la derecha","На ближайшем — направо","эн ла про́ксима, а ла дэрэ́ча"],["Cambie de carril","Перестройтесь","ка́мбье дэ карри́ль"],["Pare aquí","Остановитесь здесь","па́рэ аки́"],["Aparque aquí","Припаркуйтесь здесь","апа́ркэ аки́"],["Dé la vuelta","Развернитесь","дэ ла вуэ́льта"],["Cuando pueda","Когда сможете (когда будет безопасно)","куа́ндо пуэ́да"],["¿Puede guiarme?","Подскажите, куда ехать?","пуэ́дэ гиа́рмэ"],["Puede arrancar","Можете трогаться","пуэ́дэ арранка́р"]]},{"type":"text","text":"# Части машины и органы управления"},{"type":"table","headers":["Испанский","Что значит"],"rows":[["el volante","руль"],["el embrague","сцепление"],["el freno / el freno de mano","тормоз / ручной тормоз"],["el acelerador","газ (педаль акселератора)"],["la marcha / marcha atrás","передача / задний ход"],["el cinturón de seguridad","ремень безопасности"],["el espejo retrovisor","зеркало заднего вида"],["el intermitente","поворотник"],["las luces cortas / largas","ближний / дальний свет"],["las luces de emergencia","аварийка"],["el limpiaparabrisas","дворники"],["el chaleco reflectante","светоотражающий жилет"],["el triángulo de emergencia","знак аварийной остановки"]]},{"type":"text","text":"# Полезные слова на дороге"},{"type":"table","headers":["Испанский","Что значит"],"rows":[["la rotonda","круговой перекрёсток"],["el paso de peatones","пешеходный переход"],["el ceda el paso","знак «Уступи дорогу»"],["el semáforo","светофор"],["el carril","полоса движения"],["el adelantamiento","обгон"],["el ángulo muerto","слепая зона"],["la distancia de seguridad","безопасная дистанция"]]},{"type":"callout","tone":"success","text":"Не поняли команду — не бойтесь переспросить: *¿Puede repetir, por favor?* («Повторите, пожалуйста»)."}],"hy":[]}$j$::jsonb, now()
where not exists (select 1 from public.useful_pages where slug = 'gid-ispanskiy-dlya-praktiki');
